    ].copy()

    dept_month_ends['ym'] = dept_month_ends['Snapshot_Date'].dt.to_period('M')

    dept_hc_monthly = (
        dept_month_ends.groupby(['Department', 'ym'])['Emp_ID']
        .nunique()
        .reset_index()
